from django.utils.translation import ugettext_lazy as _
from rest_framework import serializers

from app import store

VAGUE = {"todo", "task", "stuff"}


class TaskSerializer(serializers.Serializer):
    id = serializers.IntegerField(read_only=True)
    title = serializers.CharField(max_length=60)
    done = serializers.NullBooleanField(required=False)
    due = serializers.DateTimeField(required=False, allow_null=True)
    tags = serializers.ListField(child=serializers.CharField(), required=False)

    def validate_title(self, value):
        if value.strip().lower() in VAGUE:
            raise serializers.ValidationError(_("Title is too vague."))
        return value.strip()

    def create(self, validated_data):
        return store.add(dict(validated_data))

