"""In-memory task storage: plain project code, no dependency calls."""
import datetime

SEED = [
    {"title": "Write report", "done": False, "due": datetime.datetime(2024, 5, 1, 9, 30),
     "tags": ["work"]},
    {"title": "Call Ada", "done": True, "due": None, "tags": []},
    {"title": "Plan trip", "done": None, "due": datetime.datetime(2024, 6, 2, 18, 0),
     "tags": ["home", "later"]},
]
TASKS = {}


def reset():
    TASKS.clear()
    for row in SEED:
        add(dict(row))


def add(data):
    task = {"id": len(TASKS) + 1, "title": data["title"], "done": data.get("done"),
            "due": data.get("due"), "tags": list(data.get("tags", []))}
    TASKS[task["id"]] = task
    return task


def get(pk):
    return TASKS.get(pk)


def all_tasks():
    return [TASKS[k] for k in sorted(TASKS)]

