import datetime

import pytz
from django.utils import timezone
from django.utils.http import is_safe_url
from rest_framework import status
from rest_framework.decorators import api_view
from rest_framework.pagination import PageNumberPagination
from rest_framework.response import Response

from app import store
from app.serializers import TaskSerializer

OFFICE_TZ = pytz.timezone("Europe/Paris")


class TaskPages(PageNumberPagination):
    page_size = 2


@api_view(["GET", "POST"])
def task_list(request):
    if request.method == "POST":
        serializer = TaskSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        task = serializer.save()
        return Response(TaskSerializer(task).data, status=status.HTTP_201_CREATED)
    paginator = TaskPages()
    page = paginator.paginate_queryset(store.all_tasks(), request)
    return paginator.get_paginated_response(TaskSerializer(page, many=True).data)


@api_view(["GET"])
def task_detail(request, pk):
    task = store.get(int(pk))
    if task is None:
        return Response({"detail": "Not found."}, status=status.HTTP_404_NOT_FOUND)
    return Response(TaskSerializer(task).data)


@api_view(["GET"])
def next_url(request):
    target = request.query_params.get("next", "/")
    if not is_safe_url(target, allowed_hosts={request.get_host()}):
        target = "/"
    return Response({"next": target})


@api_view(["GET"])
def office_time(request):
    naive = datetime.datetime.strptime(request.query_params["at"], "%Y-%m-%dT%H:%M")
    local = OFFICE_TZ.localize(naive)
    return Response({"utc": local.astimezone(timezone.utc).isoformat()})

