import pytest
from rest_framework.test import APIClient

from app import store


@pytest.fixture()
def client():
    store.reset()
    return APIClient()


def test_list_is_paginated(client):
    r = client.get("/tasks/")
    assert r.status_code == 200
    body = r.json()
    assert body["count"] == 3
    assert [t["title"] for t in body["results"]] == ["Write report", "Call Ada"]
    assert body["next"] == "http://testserver/tasks/?page=2"
    assert client.get("/tasks/?page=2").json()["results"][0]["done"] is None
    assert client.get("/tasks/?page=9").status_code == 404


def test_create_task(client):
    r = client.post("/tasks/", {"title": "  Ship it ", "done": None, "due": "2024-05-01T12:00:00",
                                "tags": ["release"]}, format="json")
    assert r.status_code == 201
    assert r.json() == {"id": 4, "title": "Ship it", "done": None, "due": "2024-05-01T12:00:00",
                        "tags": ["release"]}


def test_create_rejects_vague_title(client):
    r = client.post("/tasks/", {"title": "todo"}, format="json")
    assert r.status_code == 400
    assert r.json() == {"title": ["Title is too vague."]}


def test_detail(client):
    assert client.get("/tasks/1/").json()["due"] == "2024-05-01T09:30:00"
    assert client.get("/tasks/99/").status_code == 404


def test_next_url_is_local(client):
    assert client.get("/next/", {"next": "/tasks/"}).json() == {"next": "/tasks/"}
    assert client.get("/next/", {"next": "https://evil.test/"}).json() == {"next": "/"}


def test_office_time(client):
    r = client.get("/office-time/", {"at": "2024-05-01T12:00"})
    assert r.json() == {"utc": "2024-05-01T10:00:00+00:00"}

